// SSH remote deployment & management — thin Tauri command wrappers over
// clawno_core::ssh.
//
// The 5 shared deploy-step commands are generated by the macro.
// Mobile uses `include_system_fallback: false` — no apt/yum fallback.
// The additional management commands below are mobile-only.

clawno_core::define_ssh_deploy_commands!(include_system_fallback: false);

// ── Remote management commands (mobile-only) ────────────────────────────────

#[tauri::command]
pub async fn ssh_stop_instance(args: SshArgs) -> StepResult {
    if let Err(e) = ssh::validate_ssh_args(&args) {
        return StepResult::err(e);
    }
    let script = ssh::cmd_stop_gateway();
    match ssh::ssh_exec(&args, &script).await {
        Ok((_, out)) if out.contains("gateway-stopped") => {
            StepResult::ok("gateway-stopped".to_string())
        }
        Ok((_, out)) => StepResult::err(format!("stop-failed:{}", last_line(&out))),
        Err(e) => StepResult::err(e),
    }
}

