#[tauri::command]
pub async fn ssh_kill_switch(args: SshArgs) -> StepResult {
    if let Err(e) = ssh::validate_ssh_args(&args) {
        return StepResult::err(e);
    }
    let script = ssh::cmd_stop_gateway();
    match ssh::ssh_exec(&args, &script).await {
        Ok((_, out)) if out.contains("gateway-stopped") => {
            StepResult::ok("kill-switch-activated".to_string())
        }
        Ok((_, out)) => StepResult::err(format!("kill-switch-failed:{}", last_line(&out))),
        Err(e) => StepResult::err(e),
    }
}
